"""PostgreSQL smoke validator with dynamic baseline."""
from dataclasses import dataclass
import time

import psycopg


@dataclass
class PgSmokeResult:
    result: str  # "PASS" or "FAIL"
    response_time_ms: int
    details: str
    metrics: dict


def validate(*, ip: str, port: int, user: str, password: str, dbname: str,
             baseline: dict | None = None,
             row_tolerance: float = 0.95) -> PgSmokeResult:
    """Connect to PG, run SELECT 1, count rows, measure size, compare to baseline.

    baseline: optional dict with row_count + db_size_bytes from a prior PASS run.
              If absent, only the basic SELECT 1 + counts are performed and PASS
              if connection succeeds.
    """
    start = time.time()
    try:
        with psycopg.connect(
            host=ip, port=port, user=user, password=password,
            dbname=dbname, connect_timeout=30,
        ) as conn:
            with conn.cursor() as cur:
                cur.execute("SELECT 1")
                row = cur.fetchone()
                if not row or row[0] != 1:
                    return PgSmokeResult("FAIL", _ms(start), "SELECT 1 returned unexpected", {})

                cur.execute("SELECT COALESCE(SUM(n_live_tup), 0) FROM pg_stat_user_tables")
                row_count = int(cur.fetchone()[0])

                cur.execute("SELECT pg_database_size(current_database())")
                db_size = int(cur.fetchone()[0])

        metrics = {"row_count": row_count, "db_size_bytes": db_size}

        if baseline:
            base_rows = baseline.get("row_count", 0)
            base_size = baseline.get("db_size_bytes", 0)
            if base_rows > 0:
                row_ratio = row_count / base_rows
                metrics["row_ratio"] = row_ratio
                if row_ratio < row_tolerance:
                    return PgSmokeResult(
                        "FAIL", _ms(start),
                        f"row count regression: {row_count} < baseline {base_rows} * {row_tolerance}",
                        metrics,
                    )
            if base_size > 0:
                size_ratio = db_size / base_size
                metrics["size_ratio"] = size_ratio
                if size_ratio < 0.9:
                    return PgSmokeResult(
                        "FAIL", _ms(start),
                        f"db size regression: {db_size} < baseline {base_size} * 0.9",
                        metrics,
                    )

        return PgSmokeResult(
            "PASS", _ms(start),
            f"row_count={row_count}, db_size={db_size}",
            metrics,
        )
    except Exception as e:
        return PgSmokeResult("FAIL", _ms(start), str(e), {})


def _ms(start: float) -> int:
    return int((time.time() - start) * 1000)

