class WinSmokeResult:
    result: str
    response_time_ms: int
    details: str
    metrics: dict


def validate(*, ip: str, port: int = 3389, timeout: int = 30) -> WinSmokeResult:
    start = time.time()
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.settimeout(timeout)
