"""Redis smoke validator with DBSIZE + RDB staleness check."""
from dataclasses import dataclass
import time

import redis as r


@dataclass
class RedisSmokeResult:
    result: str
    response_time_ms: int
    details: str
    metrics: dict


def validate(*, ip: str, port: int, password: str | None,
             baseline: dict | None = None,
             max_rdb_age_hours: float = 24.0,
             max_retries: int = 12,
             retry_delay: float = 15.0) -> RedisSmokeResult:
    """Validate redis smoke: PING + DBSIZE + RDB age.

    Retries PING up to `max_retries` times spaced `retry_delay` seconds apart.
    Redis on a freshly-booted VM may take a minute to load the RDB and start
    accepting connections.
    """
    start = time.time()
    last_err: str | None = None
    client = None
    for attempt in range(1, max_retries + 1):
        try:
            client = r.Redis(host=ip, port=port, password=password,
                            socket_timeout=15, decode_responses=False)
            if not client.ping():
                raise RuntimeError("PING returned falsy")
            break
        except Exception as e:
            last_err = str(e)
            client = None
            if attempt < max_retries:
                time.sleep(retry_delay)

    if client is None:
        return RedisSmokeResult("FAIL", _ms(start), last_err or "PING failed", {})

    try:
        dbsize = int(client.dbsize())
        last_save = float(client.lastsave())
    except Exception as e:
        return RedisSmokeResult("FAIL", _ms(start), str(e), {})
    finally:
        try:
            client.close()
        except Exception:
            pass

    rdb_age = (time.time() - last_save) / 3600
    metrics = {"dbsize": dbsize, "rdb_age_hours": rdb_age}

    if rdb_age > max_rdb_age_hours:
        return RedisSmokeResult(
            "FAIL", _ms(start),
            f"RDB stale: {rdb_age:.1f}h > {max_rdb_age_hours}h",
            metrics,
        )

    if baseline:
        base_dbsize = baseline.get("dbsize", 0)
        if base_dbsize > 0 and dbsize < base_dbsize * 0.9:
            return RedisSmokeResult(
                "FAIL", _ms(start),
                f"dbsize regression: {dbsize} < baseline {base_dbsize} * 0.9",
                metrics,
            )

    return RedisSmokeResult("PASS", _ms(start),
                           f"dbsize={dbsize} rdb_age={rdb_age:.1f}h", metrics)


def _ms(start: float) -> int:
    return int((time.time() - start) * 1000)

"""PostgreSQL smoke validator with dynamic baseline."""
from dataclasses import dataclass
import time

import psycopg


@dataclass
class PgSmokeResult:
    result: str  # "PASS" or "FAIL"
    response_time_ms: int
    details: str
    metrics: dict


def validate(*, ip: str, port: int, user: str, password: str, dbname: str,
             baseline: dict | None = None,
             row_tolerance: float = 0.95,
             max_retries: int = 12,
             retry_delay: float = 15.0) -> PgSmokeResult:
    """Connect to PG, run SELECT 1, count rows, measure size, compare to baseline.

    baseline: optional dict with row_count + db_size_bytes from a prior PASS run.
              If absent, only the basic SELECT 1 + counts are performed and PASS
              if connection succeeds.

    Retries connection up to `max_retries` times spaced `retry_delay` seconds
    apart. Postgres on a freshly-booted VM can take a few minutes before it
    accepts connections (boot + service start + recovery).
    """
    start = time.time()
    last_err: str | None = None
    row_count = 0
    db_size = 0
    connected = False
    for attempt in range(1, max_retries + 1):
        try:
            with psycopg.connect(
                host=ip, port=port, user=user, password=password,
                dbname=dbname, connect_timeout=30,
            ) as conn:
                with conn.cursor() as cur:
                    cur.execute("SELECT 1")
                    row = cur.fetchone()
                    if not row or row[0] != 1:
                        return PgSmokeResult("FAIL", _ms(start), "SELECT 1 returned unexpected", {})

                    cur.execute("SELECT COALESCE(SUM(n_live_tup), 0) FROM pg_stat_user_tables")
                    row_count = int(cur.fetchone()[0])

                    cur.execute("SELECT pg_database_size(current_database())")
                    db_size = int(cur.fetchone()[0])
            connected = True
            break
        except Exception as e:
            last_err = str(e)
            if attempt < max_retries:
                time.sleep(retry_delay)

    if not connected:
        return PgSmokeResult("FAIL", _ms(start), last_err or "connection failed", {})

    metrics = {"row_count": row_count, "db_size_bytes": db_size}

    if baseline:
        base_rows = baseline.get("row_count", 0)
        base_size = baseline.get("db_size_bytes", 0)
        if base_rows > 0:
            row_ratio = row_count / base_rows
            metrics["row_ratio"] = row_ratio
            if row_ratio < row_tolerance:
                return PgSmokeResult(
                    "FAIL", _ms(start),
                    f"row count regression: {row_count} < baseline {base_rows} * {row_tolerance}",
                    metrics,
                )
        if base_size > 0:
            size_ratio = db_size / base_size
            metrics["size_ratio"] = size_ratio
            if size_ratio < 0.9:
                return PgSmokeResult(
                    "FAIL", _ms(start),
                    f"db size regression: {db_size} < baseline {base_size} * 0.9",
                    metrics,
                )

    return PgSmokeResult(
        "PASS", _ms(start),
        f"row_count={row_count}, db_size={db_size}",
        metrics,
    )


def _ms(start: float) -> int:
    return int((time.time() - start) * 1000)

