"""PostgreSQL smoke validator with dynamic baseline."""
from dataclasses import dataclass
import time

import psycopg


@dataclass
class PgSmokeResult:
    result: str  # "PASS" or "FAIL"
    response_time_ms: int
    details: str
    metrics: dict


def validate(*, ip: str, port: int, user: str, password: str, dbname: str,
             baseline: dict | None = None,
             row_tolerance: float = 0.95,
             max_retries: int = 12,
             retry_delay: float = 15.0) -> PgSmokeResult:
    """Connect to PG, run SELECT 1, count rows, measure size, compare to baseline.

    baseline: optional dict with row_count + db_size_bytes from a prior PASS run.
              If absent, only the basic SELECT 1 + counts are performed and PASS
              if connection succeeds.

    Retries connection up to `max_retries` times spaced `retry_delay` seconds
    apart. Postgres on a freshly-booted VM can take a few minutes before it
    accepts connections (boot + service start + recovery).
    """
    # When the secret doesn't include a database name, psycopg defaults to
    # using the connection user as dbname (which only exists if the cluster
    # has a same-named DB). Fall back to the always-present `postgres` DB
    # so the connection succeeds; the queries below still report on the
    # *currently-connected* database via pg_database_size(current_database()).
    effective_dbname = dbname if dbname else "postgres"

    start = time.time()
    last_err: str | None = None
    row_count = 0
    db_size = 0
    connected = False
    for attempt in range(1, max_retries + 1):
        try:
            with psycopg.connect(
                host=ip, port=port, user=user, password=password,
                dbname=effective_dbname, connect_timeout=30,
            ) as conn:
                with conn.cursor() as cur:
                    cur.execute("SELECT 1")
                    row = cur.fetchone()
                    if not row or row[0] != 1:
                        return PgSmokeResult("FAIL", _ms(start), "SELECT 1 returned unexpected", {})

                    cur.execute("SELECT COALESCE(SUM(n_live_tup), 0) FROM pg_stat_user_tables")
                    row_count = int(cur.fetchone()[0])

                    cur.execute("SELECT pg_database_size(current_database())")
                    db_size = int(cur.fetchone()[0])
            connected = True
            break
        except Exception as e:
            last_err = str(e)
            if attempt < max_retries:
                time.sleep(retry_delay)

    if not connected:
        return PgSmokeResult("FAIL", _ms(start), last_err or "connection failed", {})

    metrics = {"row_count": row_count, "db_size_bytes": db_size}

    if baseline:
        base_rows = baseline.get("row_count", 0)
        base_size = baseline.get("db_size_bytes", 0)
        if base_rows > 0:
            row_ratio = row_count / base_rows
            metrics["row_ratio"] = row_ratio
            if row_ratio < row_tolerance:
                return PgSmokeResult(
                    "FAIL", _ms(start),
                    f"row count regression: {row_count} < baseline {base_rows} * {row_tolerance}",
                    metrics,
                )
        if base_size > 0:
            size_ratio = db_size / base_size
            metrics["size_ratio"] = size_ratio
            if size_ratio < 0.9:
                return PgSmokeResult(
                    "FAIL", _ms(start),
                    f"db size regression: {db_size} < baseline {base_size} * 0.9",
                    metrics,
                )

    return PgSmokeResult(
        "PASS", _ms(start),
        f"row_count={row_count}, db_size={db_size}",
        metrics,
    )


def _ms(start: float) -> int:
    return int((time.time() - start) * 1000)

"""MongoDB smoke validator with dbStats baseline."""
from dataclasses import dataclass
import time

from pymongo import MongoClient


@dataclass
class MongoSmokeResult:
    result: str
    response_time_ms: int
    details: str
    metrics: dict


def validate(*, ip: str, port: int, user: str, password: str,
             baseline: dict | None = None,
             row_tolerance: float = 0.95,
             max_retries: int = 12,
             retry_delay: float = 15.0) -> MongoSmokeResult:
    """Validate mongo smoke: ping + dbStats.

    Retries connection up to `max_retries` times spaced `retry_delay` seconds
    apart. Mongo on a freshly-booted VM may take a couple of minutes before
    accepting connections (boot + journal replay + auth init).
    """
    if user:
        uri = f"mongodb://{user}:{password}@{ip}:{port}/?authSource=admin"
    else:
        uri = f"mongodb://{ip}:{port}/"

    start = time.time()
    last_err: str | None = None
    objects = 0
    data_size = 0
    connected = False
    for attempt in range(1, max_retries + 1):
        try:
            client = MongoClient(uri, serverSelectionTimeoutMS=15000)
            try:
                ping = client.admin.command("ping")
                if ping.get("ok") != 1.0:
                    raise RuntimeError(f"ping not ok: {ping}")
                stats = client.admin.command("dbStats")
                objects = int(stats.get("objects", 0))
                data_size = int(stats.get("dataSize", 0))
            finally:
                try:
                    client.close()
                except Exception:
                    pass
            connected = True
            break
        except Exception as e:
            last_err = str(e)
            if attempt < max_retries:
                time.sleep(retry_delay)

    if not connected:
        return MongoSmokeResult("FAIL", _ms(start), last_err or "connection failed", {})

    metrics = {"objects": objects, "data_size": data_size}

    if baseline:
        base_objects = baseline.get("objects", 0)
        if base_objects > 0:
            ratio = objects / base_objects
            metrics["objects_ratio"] = ratio
            if ratio < row_tolerance:
                return MongoSmokeResult(
                    "FAIL", _ms(start),
                    f"object count regression: {objects} < {base_objects} * {row_tolerance}",
                    metrics,
                )

    return MongoSmokeResult("PASS", _ms(start),
                           f"objects={objects} dataSize={data_size}", metrics)


def _ms(start: float) -> int:
    return int((time.time() - start) * 1000)

